export type TrendSortField =
  | "trend"
  | "created_at";

export interface TrendStartup {
  readonly domain?: string | null;
  readonly score?: number | null;
  readonly [key: string]: unknown;
}

/**
 * Eleven LLM-written analysis sections, ~5KB total.
 */
export interface TrendSummary {
  readonly companies_involved?: string | null;
  readonly concise_description?: string | null;
  readonly conclusion_and_key_takeaways?: string | null;
  readonly growth_evaluation?: string | null;
  readonly introduction?: string | null;
  readonly investment_and_funding?: string | null;
  readonly key_topics_and_trends?: string | null;
  readonly market_overview?: string | null;
  readonly news_and_media_coverage?: string | null;
  readonly technology_used?: string | null;
  readonly topic_analysis?: string | null;
  readonly [key: string]: unknown;
}

export type TrendTopicType =
  | "regular_topic"
  | "topic_cluster";

export interface ViaInstitution {
  readonly ended: string | null;
  readonly id: string;
  readonly kind: string | null;
  readonly match_confidence: string | null;
  readonly match_type: string;
  readonly name: string | null;
  readonly role: string | null;
  readonly started: string | null;
}

export interface VoteCastResponse {
  readonly changed: boolean;
  readonly vote: VoteView;
}

export interface VoteListResponse {
  readonly request_id: string;
  readonly votes: readonly VoteView[];
}

export interface VoteRequest {
  readonly entity_category: string;
  readonly entity_id?: string | null;
  readonly level: "result_set" | "result";
  readonly reason_code?: string | null;
  readonly request_id: string;
  readonly text?: string | null;
  readonly vote: "like" | "dislike" | "flag";
}

export interface VoteView {
  readonly entity_category: string;
  readonly entity_id: string | null;
  readonly level: string;
  readonly reason_code: string | null;
  readonly request_id: string;
  readonly text: string | null;
  readonly vote: string;
  readonly vote_id: string;
}
